<?php
require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT r.*,m.name creator FROM family_recipes r LEFT JOIN family_members m ON m.id=r.created_by_member_id WHERE r.id=?');$q->execute([$id]);$recipe=$q->fetch();if(!$recipe){http_response_code(404);exit('Rețeta nu există.');}$q=$pdo->prepare('SELECT * FROM family_recipe_ingredients WHERE recipe_id=? ORDER BY sort_order,id');$q->execute([$id]);$ingredients=$q->fetchAll();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{$listId=shopping_list_id($pdo);if($action==='add_one'){$iid=(int)($_POST['ingredient_id']??0);$x=$pdo->prepare('SELECT ingredient_text FROM family_recipe_ingredients WHERE id=? AND recipe_id=?');$x->execute([$iid,$id]);$text=(string)$x->fetchColumn();if(!$text)throw new RuntimeException('Ingredient invalid.');$ins=$pdo->prepare('INSERT INTO family_list_items(list_id,name,created_by_member_id) VALUES(?,?,?)');$ins->execute([$listId,$text,current_member_id()]);$message='Ingredient adăugat la cumpărături.';}elseif($action==='add_all'){$ins=$pdo->prepare('INSERT INTO family_list_items(list_id,name,created_by_member_id) VALUES(?,?,?)');$n=0;foreach($ingredients as $i){$ins->execute([$listId,$i['ingredient_text'],current_member_id()]);$n++;}$message=$n.' ingrediente adăugate la cumpărături.';}if($action){log_activity($pdo,'recipe_to_list','recipe',$id,$recipe['title']);}}catch(Throwable $e){$error=$e->getMessage();}}
$pageTitle=$recipe['title'];$active='more';$backUrl='/recipes.php';require __DIR__.'/includes/layout_top.php';
?>
<?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<article class="recipe-detail">
<?php if($recipe['image_path']):?><div class="recipe-detail__image"><img src="/recipe-media.php?id=<?=$id?>" alt="<?=e($recipe['title'])?>"></div><?php endif;?>
<div class="recipe-detail__intro"><div><h2><?=e($recipe['title'])?></h2><small><?=count($ingredients)?> ingrediente<?=$recipe['creator']?' · adăugată de '.e($recipe['creator']):''?></small></div><a class="btn soft small" href="/recipes.php?edit=<?=$id?>"><?=icon('edit')?> Editează</a></div>
<div class="recipe-tabs" role="tablist"><button class="active" type="button" data-recipe-tab="ingredients">Ingrediente</button><button type="button" data-recipe-tab="preparation">Preparare</button></div>
<section class="recipe-tab-panel active" data-recipe-panel="ingredients"><div class="recipe-ingredient-head"><h3>Ingrediente</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_all"><button class="btn primary small"><?=icon('cart')?> Adaugă toate</button></form></div><div class="ingredient-list"><?php foreach($ingredients as $i):?><article><span><?=icon('check')?></span><b><?=e($i['ingredient_text'])?></b><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_one"><input type="hidden" name="ingredient_id" value="<?=$i['id']?>"><button class="icon-btn" aria-label="Adaugă la cumpărături" title="Adaugă la cumpărături"><?=icon('cart')?></button></form></article><?php endforeach;?></div></section>
<section class="recipe-tab-panel" data-recipe-panel="preparation"><h3>Cum se prepară</h3><div class="recipe-preparation"><?=nl2br(e($recipe['preparation']))?></div></section>
</article>
<script>document.querySelectorAll('[data-recipe-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-recipe-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-recipe-panel]').forEach(p=>p.classList.toggle('active',p.dataset.recipePanel===b.dataset.recipeTab));}));</script>
